Scripts.Body:
# Assemble a hash-linked record for the normal-character predicate experiment.
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$repo = (Resolve-Path (Join-Path $root '../..')).Path
$output = Join-Path $repo 'Kotowari.Benchmarks/Results/experiments/2026-10-19-normal-character-predicate.json'
$baselineCommit = '00a7efa938a41e182974db822f2b2ab2dba17ff8'
$inputHash = 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D'
$libraryHash = '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8'

function Read-Json([string]$Path) {
    Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -DateKind String
}

function Get-Hash([string]$Path) {
    (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash
}

function Get-RelativePath([string]$Path) {
    [IO.Path]::GetRelativePath($repo, $Path).Replace('\', '/')
}

function Get-Tier1Method([string]$Path, [string]$Pattern, [int]$ExcerptLength = 80) {
    $lines = [IO.File]::ReadAllLines($Path)
    $startIndex = -1
    for ($index = 0; $index -lt $lines.Length; $index++) {
        if ($lines[$index] -match $Pattern) { $startIndex = $index }
    }
    if ($startIndex -lt 0) { return $null }
    $endIndex = $startIndex + 1
    while ($endIndex -lt $lines.Length -and $lines[$endIndex] -notmatch '^; Assembly listing for method') { $endIndex++ }
    $methodLines = @($lines[$startIndex..($endIndex - 1)])
    $byteLine = $methodLines | Select-String 'Total bytes of code (?<bytes>\d+)' | Select-Object -Last 1
    if (-not $byteLine) { throw "JIT code-size line was not found: $Pattern" }
    [ordered]@{
        HeaderLine = $startIndex + 1
        CodeBytes = [int]$byteLine.Matches[0].Groups['bytes'].Value
        Header = $lines[$startIndex]
        Excerpt = @($methodLines | Select-Object -First $ExcerptLength)
        ExcerptLineCount = [Math]::Min($ExcerptLength, $methodLines.Count)
    }
}

function Get-RunRecord([string]$Batch, [int]$Block, [string]$Variant) {
    $name = '{0:d2}-{1}' -f $Block, $Variant
    $directory = Join-Path $root "runs/$Batch/$name"
    $summaryPath = Join-Path $directory 'run-summary.json'
    $summary = Read-Json $summaryPath
    if ($summary.Run -ne $name -or $summary.Batch -ne $Batch -or $summary.Variant -ne $Variant -or $summary.ExitCode -ne 0 -or $summary.ActualCount -ne 8 -or $summary.ResultCount -ne 8 -or $summary.WarmupCount -ne 16) {
        throw "Run identity/status mismatch: $Batch/$name"
    }
    if ($summary.InputBytes -ne 4172062 -or $summary.InputSHA256 -ne $inputHash -or $summary.LibraryDLLSHA256 -ne $libraryHash -or $summary.DLLManifestSHA256 -ne (Get-Hash (Join-Path $root 'dll-manifest.json'))) {
        throw "Input, library, or frozen manifest mismatch: $Batch/$name"
    }
    if (@($summary.ActualIterations).Count -ne 8 -or @($summary.ResultIterations).Count -ne 8 -or @($summary.ActualIterations + $summary.ResultIterations | Where-Object Operations -ne 4).Count -ne 0) {
        throw "Iteration/invocation mismatch: $Batch/$name"
    }
    $hostLog = Join-Path $directory $summary.HostLog
    $stderrLog = Join-Path $directory $summary.Stderr
    if (-not (Test-Path -LiteralPath $hostLog) -or -not (Test-Path -LiteralPath $stderrLog) -or (Get-Item -LiteralPath $stderrLog).Length -ne 0) { throw "Run logs missing or stderr is not empty: $Batch/$name" }
    $hostText = [IO.File]::ReadAllText($hostLog)
    if ($hostText -notmatch '(?m)^// AfterAll\s*$') { throw "Run completion marker missing: $Batch/$name" }
    [ordered]@{
        Name = $name
        SummaryPath = Get-RelativePath $summaryPath
        SummarySHA256 = Get-Hash $summaryPath
        Summary = $summary
        HostLogPath = Get-RelativePath $hostLog
        HostLogSHA256 = Get-Hash $hostLog
        StderrPath = Get-RelativePath $stderrLog
        StderrSHA256 = Get-Hash $stderrLog
    }
}

function Get-BatchRecord([string]$Batch) {
    $runs = @(
        foreach ($block in 1..8) {
            foreach ($variant in 'baseline', 'candidate') { Get-RunRecord $Batch $block $variant }
        }
    )
    $summaryPath = Join-Path $root "$Batch-summary.json"
    $summary = Read-Json $summaryPath
    if ($summary.PairCount -ne 8 -or $summary.Pairs.Count -ne 8) { throw "Expected 8 pairs in $Batch." }
    $baselineAllocation = ($summary.Pairs.BaselineAllocatedBytesPerOperation | Measure-Object -Average).Average
    $candidateAllocation = ($summary.Pairs.CandidateAllocatedBytesPerOperation | Measure-Object -Average).Average
    [ordered]@{
        Summary = $summary
        SummaryPath = Get-RelativePath $summaryPath
        SummarySHA256 = Get-Hash $summaryPath
        BaselineMeanAllocatedBytesPerParse = $baselineAllocation
        CandidateMeanAllocatedBytesPerParse = $candidateAllocation
        Runs = $runs
    }
}

if (Test-Path -LiteralPath $output) { throw "Refusing to overwrite existing evidence: $output" }

$exploration = Get-BatchRecord 'exploration'
$confirmation = Get-BatchRecord 'confirmation'
if ($exploration.Summary.Confidence95.Upper -ge 1 -or $confirmation.Summary.Confidence95.Upper -ge 1) { throw 'Predeclared exploration/confirmation gate did not pass.' }

$manifestPath = Join-Path $root 'dll-manifest.json'
$manifest = Read-Json $manifestPath
foreach ($variant in 'baseline', 'candidate') {
    if ($manifest.$variant.Count -ne 28 -or ($manifest.$variant | Where-Object Name -eq 'Marimo.Kotowari.dll').SHA256 -ne $libraryHash) { throw "Frozen host mismatch: $variant" }
    foreach ($item in $manifest.$variant) {
        if ((Get-Hash (Join-Path $root "$variant/host/$($item.Name)")) -ne $item.SHA256) { throw "Frozen DLL mismatch: $variant/$($item.Name)" }
    }
}
$dllDifferences = @(
    foreach ($base in $manifest.baseline) {
        $other = $manifest.candidate | Where-Object Name -eq $base.Name
        if (-not $other -or $other.SHA256 -ne $base.SHA256) { $base.Name }
    }
)
if ($dllDifferences.Count -ne 1 -or $dllDifferences[0] -ne 'Marimo.Parser.dll') { throw "Expected only Marimo.Parser.dll to differ: $($dllDifferences -join ', ')" }

$baselineValidation = Read-Json (Join-Path $root 'baseline/validation.json')
$candidateValidation = Read-Json (Join-Path $root 'candidate/validation.json')
foreach ($validation in @($baselineValidation, $candidateValidation)) {
    if ($validation.ExitCode -ne 0 -or $validation.InputBytes -ne 4172062 -or $validation.InputSHA256 -ne $inputHash -or -not $validation.FullInputConsumed -or $validation.ExpectedNodeCount -ne 100001 -or -not $validation.SystemTextJsonTreeEquivalent -or $validation.LibrarySHA256 -ne $libraryHash) { throw "Full-input/result-tree validation failed: $($validation.Variant)" }
}

$environmentPath = Join-Path $root 'environment.json'
$environment = @(Read-Json $environmentPath)
$environmentRecords = @(
    foreach ($record in $environment) {
        if ($record.ACLineStatus -ne 1 -or $record.BatterySaver -ne 0) { throw "AC or Battery Saver condition mismatch: $($record.Stage)" }
        [ordered]@{ Stage = $record.Stage; TimestampUTC = $record.TimestampUTC; ACLineStatus = $record.ACLineStatus; BatterySaver = $record.BatterySaver; ActiveDotnetProcesses = $record.ActiveDotnetProcesses }
    }
)
$helperPath = Join-Path $repo 'artifacts/string-next-after-whitespace-2026-10-19/power-helper-status.json'
$helper = Read-Json $helperPath
if ($helper.Reason -ne 'Running' -or [long]$helper.AcquireReturn -ne 2147483648 -or $helper.CurrentPower.ACLineStatus -ne 1 -or $helper.CurrentPower.BatterySaver) { throw 'Shared sleep-prevention helper was not confirmed active in its recorded status.' }

$parentValidationPath = Join-Path $repo 'artifacts/string-next-after-whitespace-2026-10-19/parent-validation.json'
$parentValidation = Read-Json $parentValidationPath
if ($parentValidation.BaselineCommit -ne $baselineCommit -or $parentValidation.CandidateJsonSourceSHA256 -ne (Get-Hash (Join-Path $repo 'JsonParser/JSON.cs')) -or $parentValidation.CandidateJsonAssemblySHA256 -ne $manifest.candidate.Where({$_.Name -eq 'Marimo.Parser.dll'}).SHA256) { throw 'Parent validation does not match the frozen candidate source/assembly.' }

$patch = (& git -C $repo diff --binary $baselineCommit -- JsonParser/JSON.cs | Out-String)
if ($LASTEXITCODE -ne 0 -or $patch -notmatch 'ConditionalCharParser' -or $patch -notmatch 'ExpectCharParser') { throw 'Candidate source diff is missing or differs from the measured change.' }
$patchPath = Join-Path $root 'candidate.patch'
[IO.File]::WriteAllText($patchPath, $patch, [Text.UTF8Encoding]::new($false))

$jitRecords = [ordered]@{}
foreach ($variant in 'baseline', 'candidate') {
    $captureRoot = Join-Path $root "diagnostics/jit/$variant/capture-01"
    $capturePath = Join-Path $captureRoot 'capture.json'
    $capture = Read-Json $capturePath
    if ($capture.ExitCode -ne 0 -or $capture.ActualCount -ne 8 -or $capture.ResultCount -ne 8 -or -not $capture.DiagnosticOnly -or $capture.LibrarySHA256 -ne $libraryHash) { throw "JIT diagnostic mismatch: $variant" }
    $asmPath = Join-Path $captureRoot 'jit.asm'
    $methods = [ordered]@{
        ExpectCharParserTier1 = Get-Tier1Method $asmPath '^; Assembly listing for method Marimo\.Kotowari\.Core\.ExpectCharParser:ParseCore.*\(Tier1\)$'
        OrParserCharTier1 = Get-Tier1Method $asmPath '^; Assembly listing for method Marimo\.Kotowari\.Core\.OrParser`1\[char\]:ParseCore.*\(Tier1\)$'
        ConditionalCharParserTier1 = Get-Tier1Method $asmPath '^; Assembly listing for method Marimo\.Kotowari\.Core\.ConditionalCharParser:ParseCore.*\(Tier1\)$'
        WhitespacePredicateB37_0Tier1 = Get-Tier1Method $asmPath '^; Assembly listing for method Marimo\.Parser\.JSON\+<>c:<\.cctor>b__37_0\(char\):bool:this \(Tier1\)$'
    }
    if ($variant -eq 'candidate') {
        $methods['NormalCharacterPredicateB37_9Tier1'] = Get-Tier1Method $asmPath '^; Assembly listing for method Marimo\.Parser\.JSON\+<>c:<\.cctor>b__37_9\(char\):bool:this \(Tier1\)$'
    }
    if ($variant -eq 'baseline' -and -not $methods.ExpectCharParserTier1) { throw 'Baseline JIT did not contain the targeted ExpectCharParser Tier1 method.' }
    if ($variant -eq 'candidate' -and $methods.ExpectCharParserTier1) { throw 'Candidate JIT unexpectedly retained ExpectCharParser Tier1.' }
    if ($variant -eq 'candidate' -and (-not $methods.NormalCharacterPredicateB37_9Tier1 -or -not $methods.WhitespacePredicateB37_0Tier1)) { throw 'Candidate ordinary-character and whitespace predicate JIT methods were not both found.' }
    $jitRecords[$variant] = [ordered]@{
        Capture = $capture
        CapturePath = Get-RelativePath $capturePath
        CaptureSHA256 = Get-Hash $capturePath
        AssemblyPath = Get-RelativePath $asmPath
        AssemblySHA256 = Get-Hash $asmPath
        AssemblyBytes = (Get-Item -LiteralPath $asmPath).Length
        Tier1Methods = $methods
        MethodIdentityNote = 'JSON b__37_9(char) is the normal-character exclusion predicate introduced in this experiment. JSON b__37_0(char) is the pre-existing whitespace predicate. They are not interchangeable.'
    }
}

$scriptRecords = @(
    foreach ($file in @(Get-ChildItem -LiteralPath $root -Recurse -File -Filter '*.ps1' | Sort-Object FullName)) {
        [ordered]@{ Path = Get-RelativePath $file.FullName; SHA256 = Get-Hash $file.FullName; Body = [IO.File]::ReadAllText($file.FullName) }
    }
)
$records = [ordered]@{
    Schema = 'kotowari-json-normal-character-predicate-evidence-v1'
    Experiment = '2026-10-19-normal-character-predicate'
    Decision = [ordered]@{
        Status = 'Both predeclared paired log-t gates passed; measured candidate remains uncommitted for review.'
        Rule = 'Proceed to independent confirmation only if exploration 95% paired log-t interval upper bound is below 1. Candidate passes the measurement gate only if confirmation upper bound is also below 1.'
        ExplorationGatePassed = ($exploration.Summary.Confidence95.Upper -lt 1)
        ConfirmationGatePassed = ($confirmation.Summary.Confidence95.Upper -lt 1)
        Interpretation = 'This comparison covers only full-file JSON StringInput parsing with the frozen sample and machine. It does not establish a general speedup for other parsers, inputs, or environments.'
    }
    Change = [ordered]@{
        BaselineCommit = $baselineCommit
        Description = 'Replace JSON JChar ordinary-character ExpectCharParser(OrParser(DoubleQuote, BackSlash)) with the existing ConditionalCharParser rejecting only quote and backslash. Escape handling, control-character branch, library code, and public APIs are unchanged.'
        CandidateSourcePath = 'JsonParser/JSON.cs'
        CandidateSourceSHA256 = Get-Hash (Join-Path $repo 'JsonParser/JSON.cs')
        CandidatePatchPath = Get-RelativePath $patchPath
        CandidatePatchSHA256 = Get-Hash $patchPath
        CandidatePatch = $patch
        ParentValidationPath = Get-RelativePath $parentValidationPath
        ParentValidationSHA256 = Get-Hash $parentValidationPath
        ParentValidation = $parentValidation
    }
    Input = [ordered]@{ Path = 'Kotowari.Benchmarks/Data/test.json'; Bytes = 4172062; SHA256 = $inputHash; ExpectedNodeCount = 100001 }
    FrozenHosts = [ordered]@{
        DLLCountPerVariant = 28
        DLLManifestPath = Get-RelativePath $manifestPath
        DLLManifestSHA256 = Get-Hash $manifestPath
        DLLManifest = $manifest
        DLLDifferences = $dllDifferences
        FixedLibrarySHA256 = $libraryHash
        BaselineParserSHA256 = ($manifest.baseline | Where-Object Name -eq 'Marimo.Parser.dll').SHA256
        CandidateParserSHA256 = ($manifest.candidate | Where-Object Name -eq 'Marimo.Parser.dll').SHA256
        BaselineSourceOrigin = 'Frozen DLLs copied from artifacts/string-whitespace-predicate-2026-10-19/candidate/host; the prior whitespace measurement candidate is this experiment baseline.'
        CandidateSourceOrigin = 'Baseline host copied into candidate/host; only Marimo.Parser.dll and its PDB were replaced with the parent-validated Release output.'
        HostValidation = [ordered]@{ Baseline = $baselineValidation; Candidate = $candidateValidation }
        ValidationInterpretation = 'Both hosts consumed the full input, produced 100,001 nodes, and matched the System.Text.Json result tree.'
    }
    Workload = [ordered]@{
        Method = 'Marimo.Kotowari.Benchmarks.JsonStreamBenchmarks.StringInput'
        Description = 'MemoryStream creation/copy -> UTF-8 decode to string -> full JSON parse/tree creation; physical disk I/O excluded.'
        Runtime = $exploration.Runs[0].Summary.Runtime
        BenchmarkDotNet = $exploration.Runs[0].Summary.BenchmarkDotNet
        TieredPGO = 1; AffinityMask = 4; WarmupCount = 16; ActualCount = 8; ResultCount = 8; InvocationCount = 4; IterationCount = 8; LaunchCount = 1; UnrollFactor = 1; OutlierMode = 'DontRemove'
        InputBytes = 4172062; InputSHA256 = $inputHash; ProcessModel = 'Every launch used a fresh dotnet process.'
    }
    Validation = [ordered]@{
        TestsBuildFormat = $parentValidation
        TestInterpretation = 'Release tests passed (248 library + 63 JSON, 0 failed, 0 skipped); non-incremental Release/analyzer build succeeded. Format returned exit code 2 with the same 66 pre-existing diagnostics and no new changed-line diagnostics; it is not represented as success.'
    }
    FormalExploration = $exploration
    IndependentConfirmation = $confirmation
    Environment = [ordered]@{
        Records = $environmentRecords
        RecordsPath = Get-RelativePath $environmentPath
        RecordsSHA256 = Get-Hash $environmentPath
        PerBlockLogStatus = [ordered]@{
            Exploration = [ordered]@{ RecordedBeforeBlocks = @(1, 3, 4, 5, 6, 7, 8); MissingBeforeBlock = 2; MissingReason = 'The original environment-sampling script rejected the block-specific Stage before starting its three-second sample. No after-the-fact record is substituted.' }
            Confirmation = [ordered]@{ RecordedBeforeBlocks = @(1, 2, 3, 4, 5, 6, 7, 8); MissingBeforeBlocks = @() }
            PowerReadiness = [ordered]@{ CheckedBeforeAll16Blocks = $true; AllChecksReportedAC = 1; BatterySaver = 0; HelperPid = $helper.Pid; HelperAcquireReturn = $helper.AcquireReturn; OutputWasCapturedPerBlockInTaskHistory = $true; SeparateReadinessLogFileWasNotPersisted = $true }
        }
        SleepPreventionHelper = [ordered]@{ StatusPath = Get-RelativePath $helperPath; StatusSHA256 = Get-Hash $helperPath; Snapshot = $helper; Release = $null }
        Interpretation = 'Every block had a successful AC/saver/helper readiness check. The per-block external dotnet-CPU sample is missing only for exploration block 2; it is explicitly reported as missing. Confirmation has all eight pre-block samples and a post-batch sample.'
    }
    JITDiagnostic = [ordered]@{
        Records = $jitRecords
        Interpretation = 'Diagnostic-only separate launches are excluded from timing. Baseline Tier1 includes ExpectCharParser<char>.ParseCore for the targeted ordinary-character path; candidate does not. Candidate b__37_9 is the new ordinary-character predicate (21 bytes); b__37_0 is the pre-existing whitespace predicate (36 bytes). Parent code review found that candidate ConditionalCharParser Tier1 still contains the shared whitespace-predicate delegate guard, so this is not a claim of complete PGO independence. The targeted inner two-alternative scan, repeated Current reads and IgnoreCase branch, plus the final ExpectCharParser Current reread, are removed. Native code-size is not treated as a measured speed effect.'
        Limitations = @('ConditionalCharParser Tier1 uses a shared delegate-type profile that includes other predicates.', 'JIT output depends on this runtime and TieredPGO profile.', 'No CPU sampling was performed for this experiment.')
    }
    Replay = [ordered]@{
        ArtifactRoot = Get-RelativePath $root
        Scripts = $scriptRecords
        RawLogs = [ordered]@{ Retention = 'Full host logs remain in the ignored artifact root; this evidence stores their relative paths and SHA-256 hashes, not duplicate raw log text.'; Source = 'Each run-summary.json HostLog/Stderr entry.' }
        RunSummaries = [ordered]@{ ExplorationPath = $exploration.SummaryPath; ExplorationSHA256 = $exploration.SummarySHA256; ConfirmationPath = $confirmation.SummaryPath; ConfirmationSHA256 = $confirmation.SummarySHA256 }
    }
}

$json = ConvertTo-Json -InputObject $records -Depth 60
if ($json -match '(?i)[A-Z]:\\Users\\|[A-Z]:/Users/') { throw 'Evidence contains a user-specific absolute path.' }
$utf8 = [Text.UTF8Encoding]::new($true)
$savedText = ($json -replace "`r?`n", "`r`n") + "`r`n"
[IO.File]::WriteAllBytes($output, $utf8.GetPreamble() + $utf8.GetBytes($savedText))
$savedBytes = [IO.File]::ReadAllBytes($output)
if ($savedBytes.Length -lt 4 -or $savedBytes[0] -ne 0xEF -or $savedBytes[1] -ne 0xBB -or $savedBytes[2] -ne 0xBF) { throw 'Evidence JSON is missing its UTF-8 BOM.' }
$text = [Text.UTF8Encoding]::new($false).GetString($savedBytes, 3, $savedBytes.Length - 3)
if ([regex]::Matches($text, "(?<!`r)`n").Count -ne 0 -or [regex]::Matches($text, "`r`n").Count -eq 0) { throw 'Evidence JSON line endings are not uniformly CRLF.' }
$loaded = ConvertFrom-Json -InputObject $text -DateKind String
if ($loaded.FormalExploration.Summary.PairCount -ne 8 -or $loaded.IndependentConfirmation.Summary.PairCount -ne 8 -or $loaded.FrozenHosts.HostValidation.Candidate.FullInputConsumed -ne $true) { throw 'Evidence round-trip verification failed.' }
Write-Output ([ordered]@{
    Path = Get-RelativePath $output
    SHA256 = Get-Hash $output
    Bytes = $savedBytes.Length
    BOM = $true
    CRLF = [regex]::Matches($text, "`r`n").Count
    BareLF = [regex]::Matches($text, "(?<!`r)`n").Count
    ExplorationRatio = $loaded.FormalExploration.Summary.PairedGeometricMeanRatio
    ExplorationConfidence95 = $loaded.FormalExploration.Summary.Confidence95
    ConfirmationRatio = $loaded.IndependentConfirmation.Summary.PairedGeometricMeanRatio
    ConfirmationConfidence95 = $loaded.IndependentConfirmation.Summary.Confidence95
    Launches = $loaded.FormalExploration.Runs.Count + $loaded.IndependentConfirmation.Runs.Count
    RawLogsEmbedded = $false
} | ConvertTo-Json -Depth 4 -Compress)

# Freeze the DLL hashes for the copied baseline and candidate hosts.
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$variants = [ordered]@{}
foreach ($variant in 'baseline', 'candidate') {
    $hostRoot = Join-Path $root "$variant/host"
    $dlls = @(Get-ChildItem -LiteralPath $hostRoot -File -Filter '*.dll' | Sort-Object Name)
    if ($dlls.Count -ne 28) { throw "$variant host must contain exactly 28 DLLs; found $($dlls.Count)." }
    $variants[$variant] = @(
        foreach ($dll in $dlls) {
            [ordered]@{
                Name = $dll.Name
                SHA256 = (Get-FileHash -LiteralPath $dll.FullName -Algorithm SHA256).Hash
            }
        }
    )
}
$differences = @(
    foreach ($baselineDll in $variants.baseline) {
        $candidateDll = $variants.candidate | Where-Object Name -eq $baselineDll.Name
        if (-not $candidateDll -or $candidateDll.SHA256 -ne $baselineDll.SHA256) { $baselineDll.Name }
    }
)
if ($differences.Count -ne 1 -or $differences[0] -ne 'Marimo.Parser.dll') {
    throw "Expected only Marimo.Parser.dll to differ; found: $($differences -join ', ')."
}
foreach ($variant in 'baseline', 'candidate') {
    if (($variants[$variant] | Where-Object Name -eq 'Marimo.Kotowari.dll').SHA256 -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') {
        throw "$variant host must retain the fixed baseline Kotowari DLL."
    }
}
$manifest = [ordered]@{ baseline = $variants.baseline; candidate = $variants.candidate }
$manifest | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $root 'dll-manifest.json') -Encoding utf8
Write-Output "DLL manifest frozen; changed DLL: $($differences[0])."

# Freeze the reused baseline host from the preceding whitespace-predicate candidate.
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$sourceManifest = Join-Path $root '../string-whitespace-predicate-2026-10-19/dll-manifest.json'
$old = Get-Content -LiteralPath $sourceManifest -Raw | ConvertFrom-Json
$dlls = @($old.candidate)
if ($dlls.Count -ne 28) { throw "Expected 28 DLLs in the reused prior candidate manifest; found $($dlls.Count)." }
foreach ($dll in $dlls) {
    $path = Join-Path $root "baseline/host/$($dll.Name)"
    if (-not (Test-Path -LiteralPath $path) -or (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -ne $dll.SHA256) {
        throw "Reused baseline host does not match the prior candidate manifest: $($dll.Name)"
    }
}
$input = $dlls | Where-Object Name -eq 'Marimo.Kotowari.dll'
if ($input.SHA256 -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') {
    throw 'Reused baseline does not retain the fixed Kotowari DLL.'
}
$manifest = [ordered]@{ baseline = $dlls }
$manifest | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $root 'baseline-dll-manifest.json') -Encoding utf8
Write-Output "Reused baseline host manifest verified: $((Get-FileHash (Join-Path $root 'baseline-dll-manifest.json') -Algorithm SHA256).Hash)"

param([Parameter(Mandatory)][string]$Stage)

$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
Add-Type -TypeDefinition @'
using System.Runtime.InteropServices;
[StructLayout(LayoutKind.Sequential)]
public struct Round2PowerStatus {
    public byte ACLineStatus;
    public byte BatteryFlag;
    public byte BatteryLifePercent;
    public byte SystemStatusFlag;
    public uint BatteryLifeTime;
    public uint BatteryFullLifeTime;
}
public static class Round2PowerStatusApi {
    [DllImport("kernel32.dll", SetLastError=true)]
    public static extern bool GetSystemPowerStatus(out Round2PowerStatus status);
}
'@

$status = New-Object Round2PowerStatus
if (-not [Round2PowerStatusApi]::GetSystemPowerStatus([ref]$status)) { throw "GetSystemPowerStatus failed: $([Runtime.InteropServices.Marshal]::GetLastWin32Error())" }
$scheme = ((powercfg.exe /getactivescheme) -join ' ')
$first = @(Get-Process dotnet -ErrorAction SilentlyContinue | Select-Object Id,CPU)
$sampleStart = [DateTime]::UtcNow
Start-Sleep -Seconds 3
$sampleEnd = [DateTime]::UtcNow
$second = @(Get-Process dotnet -ErrorAction SilentlyContinue | Select-Object Id,CPU)
$activity = @(
    foreach ($process in $second) {
        $prior = $first | Where-Object Id -eq $process.Id | Select-Object -First 1
        if ($prior -and $null -ne $process.CPU -and $null -ne $prior.CPU -and $process.CPU -gt $prior.CPU) {
            [ordered]@{ProcessId=$process.Id;DeltaCpuSeconds=($process.CPU-$prior.CPU)}
        }
    }
)
$record = [ordered]@{
    Stage=$Stage
    TimestampUTC=[DateTime]::UtcNow.ToString('o')
    SampleStartUTC=$sampleStart.ToString('o')
    SampleEndUTC=$sampleEnd.ToString('o')
    ACLineStatus=[int]$status.ACLineStatus
    BatteryFlag=[int]$status.BatteryFlag
    BatteryLifePercent=[int]$status.BatteryLifePercent
    BatterySaver=[int]$status.SystemStatusFlag
    PowerScheme=$scheme
    DotnetCpuActivityWindowSeconds=3
    ActiveDotnetProcesses=$activity
}
$path = Join-Path $root 'environment.json'
$records = [Collections.Generic.List[object]]::new()
if (Test-Path $path) {
    foreach ($existing in @(Get-Content -Raw $path | ConvertFrom-Json)) { $records.Add($existing) }
}
$records.Add([pscustomobject]$record)
ConvertTo-Json -InputObject @($records.ToArray()) -Depth 6 | Set-Content -LiteralPath $path -Encoding utf8
Write-Output ('{0}: ACLine={1}; BatterySaver={2}; active dotnet CPU processes={3}' -f $Stage,$record.ACLineStatus,$record.BatterySaver,$activity.Count)

# ProcessStartInfo.ArgumentList requires PowerShell 7.
#requires -Version 7.0
param(
    [ValidateSet('exploration','confirmation')][string]$Batch = 'exploration',
    [Parameter(Mandatory)][ValidateRange(1,8)][int]$Block
)

$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$expectedInputHash = 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D'
$dllManifestPath = Join-Path $root 'dll-manifest.json'
$dllManifest = Get-Content -Raw -LiteralPath $dllManifestPath | ConvertFrom-Json
foreach ($variant in 'baseline', 'candidate') {
    if (($dllManifest.$variant | Where-Object Name -eq 'Marimo.Kotowari.dll').SHA256 -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') { throw "$variant manifest does not retain the fixed Kotowari DLL." }
}
$parserHashes = @(
    ($dllManifest.baseline | Where-Object Name -eq 'Marimo.Parser.dll').SHA256
    ($dllManifest.candidate | Where-Object Name -eq 'Marimo.Parser.dll').SHA256
) | Sort-Object -Unique
if ($parserHashes.Count -ne 2) { throw 'Expected Marimo.Parser.dll to be the only changed host DLL.' }
$dllDifferences = @(
    foreach ($baseDll in $dllManifest.baseline) {
        $candidateDll = $dllManifest.candidate | Where-Object Name -eq $baseDll.Name
        if (-not $candidateDll -or $candidateDll.SHA256 -ne $baseDll.SHA256) { $baseDll.Name }
    }
)
if ($dllDifferences.Count -ne 1 -or $dllDifferences[0] -ne 'Marimo.Parser.dll') { throw "Unexpected frozen DLL differences: $($dllDifferences -join ', ')." }
$cases = if ($Block % 2 -eq 1) { @('baseline','candidate') } else { @('candidate','baseline') }

foreach ($variant in $cases) {
    $runName = '{0:d2}-{1}' -f $Block,$variant
    $runRoot = Join-Path $root "runs/$Batch/$runName"
    $summaryPath = Join-Path $runRoot 'run-summary.json'
    if (Test-Path -LiteralPath $summaryPath) {
        $existing = Get-Content -Raw -LiteralPath $summaryPath | ConvertFrom-Json
        if ($existing.Run -ne $runName -or $existing.Batch -ne $Batch -or $existing.Variant -ne $variant -or $existing.InputSHA256 -ne $expectedInputHash -or $existing.ActualCount -ne 8 -or $existing.ResultCount -ne 8) { throw "Existing completed run summary is invalid: $runName" }
        Write-Output "Preserving completed $runName."
        continue
    }
    if (Test-Path -LiteralPath $runRoot) {
        if (@(Get-ChildItem -LiteralPath $runRoot -Force).Count -gt 0) { throw "Existing incomplete output cannot be resumed safely: $runRoot" }
    } else {
        $null = New-Item -ItemType Directory -Path $runRoot -Force
    }
    $hostRoot = Join-Path $root "$variant/host"
    $child = Join-Path $hostRoot 'StringExecutionRecovery.ChildHarness.dll'
    $measurement = Join-Path $hostRoot 'StringExecutionRecovery.Measurement.dll'
    $inputPath = Join-Path $hostRoot 'Data/test.json'
    if ((Get-FileHash -LiteralPath $inputPath -Algorithm SHA256).Hash -ne $expectedInputHash) { throw "Input hash mismatch: $variant" }

    $expectedDlls = @($dllManifest.$variant)
    if ($expectedDlls.Count -ne 28) { throw "Expected 28 frozen DLLs for $variant." }
    foreach ($expected in $expectedDlls) {
        $path = Join-Path $hostRoot $expected.Name
        if (-not (Test-Path -LiteralPath $path) -or (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -ne $expected.SHA256) { throw "Frozen DLL mismatch: $variant/$($expected.Name)" }
    }
    $childHash = (Get-FileHash -LiteralPath $child -Algorithm SHA256).Hash
    $measurementHash = (Get-FileHash -LiteralPath $measurement -Algorithm SHA256).Hash

    $start = [Diagnostics.ProcessStartInfo]::new('dotnet')
    $start.WorkingDirectory = $hostRoot
    $start.UseShellExecute = $false
    $start.CreateNoWindow = $true
    $start.RedirectStandardOutput = $true
    $start.RedirectStandardError = $true
    foreach ($argument in @('StringExecutionRecovery.ChildHarness.dll','--benchmarkName','Marimo.Kotowari.Benchmarks.JsonStreamBenchmarks.StringInput','--benchmarkId','0')) { [void]$start.ArgumentList.Add($argument) }
    $start.Environment['DOTNET_TieredPGO'] = '1'
    $process = $null
    $processId = $null
    $exitCode = $null
    $endedUtc = $null
    $startedUtc = [DateTime]::UtcNow
    $watch = [Diagnostics.Stopwatch]::StartNew()
    try {
        $process = [Diagnostics.Process]::Start($start)
        if (-not $process) { throw "Could not start $runName" }
        $processId = $process.Id
        $process.ProcessorAffinity = [IntPtr]4
        if ($process.ProcessorAffinity.ToInt64() -ne 4) { throw "Affinity mismatch: $runName" }
        $stdoutTask = $process.StandardOutput.ReadToEndAsync()
        $stderrTask = $process.StandardError.ReadToEndAsync()
        while (-not $process.WaitForExit(1000)) { if ($watch.Elapsed.TotalSeconds -gt 180) { throw "Timed out: $runName" } }
        $exitCode = $process.ExitCode
        $endedUtc = [DateTime]::UtcNow
        $stdout = $stdoutTask.GetAwaiter().GetResult()
        $stderr = $stderrTask.GetAwaiter().GetResult()
        [IO.File]::WriteAllText((Join-Path $runRoot 'host.log'),$stdout,[Text.UTF8Encoding]::new($false))
        [IO.File]::WriteAllText((Join-Path $runRoot 'stderr.log'),$stderr,[Text.UTF8Encoding]::new($false))
        if ($exitCode -ne 0) { throw "Exit code $exitCode`: $runName" }
        if ($stderr.Trim().Length -ne 0) { throw "Unexpected stderr: $runName" }
        if ($stdout -notmatch '(?m)^// AfterAll\s*$') { throw "Missing completion marker: $runName" }
        if ((Get-FileHash -LiteralPath $child -Algorithm SHA256).Hash -ne $childHash -or (Get-FileHash -LiteralPath $measurement -Algorithm SHA256).Hash -ne $measurementHash) { throw "Harness changed during run: $runName" }
        foreach ($expected in $expectedDlls) { if ((Get-FileHash -LiteralPath (Join-Path $hostRoot $expected.Name) -Algorithm SHA256).Hash -ne $expected.SHA256) { throw "Frozen DLL changed during run: $variant/$($expected.Name)" } }
    } catch {
        [IO.File]::WriteAllText((Join-Path $runRoot 'runner-error.log'),$_.ToString(),[Text.UTF8Encoding]::new($false))
        throw
    } finally {
        if ($process) {
            if (-not $process.HasExited) { $process.Kill(); $process.WaitForExit() }
            $process.Dispose()
        }
    }

    $rows = @([regex]::Matches($stdout,'(?m)^Workload(?<stage>Warmup|Actual|Result)\s+(?<index>\d+):\s+(?<ops>\d+) op, (?<ns>[\d.]+) ns, (?<display>[\d.]+) (?<unit>ns|us|μs|µs|ms|s)/op') | ForEach-Object {
        $multiplier = switch ($_.Groups['unit'].Value) { 'ns' {1.0} 'us' {1e3} 'μs' {1e3} 'µs' {1e3} 'ms' {1e6} 's' {1e9} }
        [ordered]@{ Stage=$_.Groups['stage'].Value; Iteration=[int]$_.Groups['index'].Value; Operations=[int]$_.Groups['ops'].Value; TotalNanoseconds=[double]::Parse($_.Groups['ns'].Value,[Globalization.CultureInfo]::InvariantCulture); DisplayNsPerOperation=([double]::Parse($_.Groups['display'].Value,[Globalization.CultureInfo]::InvariantCulture)*$multiplier) }
    })
    foreach ($stage in 'Warmup','Actual','Result') {
        $expectedCount = if ($stage -eq 'Warmup') {16} else {8}
        $stageRows = @($rows | Where-Object Stage -eq $stage)
        if ($stageRows.Count -ne $expectedCount -or @($stageRows | Where-Object Operations -ne 4).Count -gt 0) { throw "Unexpected $stage observations: $runName" }
    }
    if ($stdout -notmatch '(?m)^// Job: .*OutlierMode=DontRemove.*Affinity=(?:0{0,61})100.*InvocationCount=4.*IterationCount=8.*LaunchCount=1.*UnrollFactor=1.*WarmupCount=16') { throw "Benchmark job settings mismatch: $runName" }
    $actualRows = @($rows | Where-Object Stage -eq 'Actual')
    $resultRows = @($rows | Where-Object Stage -eq 'Result')
    $gc = [regex]::Match($stdout,'(?m)^// GC:\s+(?<g0>\d+)\s+(?<g1>\d+)\s+(?<g2>\d+)\s+(?<bytes>\d+)\s+(?<ops>\d+)')
    if (-not $gc.Success -or [int]$gc.Groups['ops'].Value -ne 4) { throw "Allocation counters missing: $runName" }
    $record = [ordered]@{
        Run=$runName; Batch=$Batch; Variant=$variant; Method='StringInput'
        MeanNs=(($resultRows | ForEach-Object {$_.TotalNanoseconds/4} | Measure-Object -Average).Average)
        ActualMeanNs=(($actualRows | ForEach-Object {$_.TotalNanoseconds/4} | Measure-Object -Average).Average)
        ActualIterations=@($actualRows | ForEach-Object {[ordered]@{BdnNanoseconds=$_.TotalNanoseconds;Operations=$_.Operations;NsPerOperation=($_.TotalNanoseconds/4)}})
        ResultIterations=@($resultRows | ForEach-Object {[ordered]@{BdnNanoseconds=$_.TotalNanoseconds;Operations=$_.Operations;NsPerOperation=($_.TotalNanoseconds/4)}})
        ActualCount=$actualRows.Count; ResultCount=$resultRows.Count; WarmupCount=16
        AllocatedBytesPerOperation=([long]$gc.Groups['bytes'].Value/[long]$gc.Groups['ops'].Value)
        GC=@([int]$gc.Groups['g0'].Value,[int]$gc.Groups['g1'].Value,[int]$gc.Groups['g2'].Value)
        Runtime=([regex]::Match($stdout,'(?m)^// Runtime=(?<v>.+)$').Groups['v'].Value)
        BenchmarkDotNet=([regex]::Match($stdout,'(?m)^// BenchmarkDotNet v(?<v>\S+)').Groups['v'].Value)
        Job=([regex]::Match($stdout,'(?m)^// Job: (?<v>.+)$').Groups['v'].Value)
        TieredPGO=1; Affinity=4; ProcessId=$processId; ExitCode=$exitCode; StartUTC=$startedUtc.ToString('o'); EndUTC=$endedUtc.ToString('o'); WallSeconds=$watch.Elapsed.TotalSeconds; InputBytes=(Get-Item $inputPath).Length; InputSHA256=$expectedInputHash
        AssemblySHA256=$childHash; MeasurementHostAssemblySHA256=$measurementHash
        LibraryDLLSHA256=(Get-FileHash (Join-Path $hostRoot 'Marimo.Kotowari.dll') -Algorithm SHA256).Hash
        DLLManifestSHA256=(Get-FileHash $dllManifestPath -Algorithm SHA256).Hash
        HostLog='host.log'; Stderr='stderr.log'
    }
    $record | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $runRoot 'run-summary.json') -Encoding utf8
    Write-Output ('Completed {0}: {1:F3} ms/parse, 8 Actual and 8 Result.' -f $runName,($record.MeanNs/1e6))
}

# JIT-only capture using the frozen generated BenchmarkDotNet ChildHarness.
# This run is a code-generation diagnostic and is not included in timing statistics.
#requires -Version 7.0
param(
    [Parameter(Mandatory)][ValidateSet('baseline','candidate')][string]$Variant
)

$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$hostRoot = Join-Path $root "$Variant/host"
$runRoot = Join-Path $root "diagnostics/jit/$Variant/capture-01"
if (Test-Path -LiteralPath $runRoot) { throw "Refusing to overwrite existing capture: $runRoot" }
$manifest = Get-Content -LiteralPath (Join-Path $root 'dll-manifest.json') -Raw | ConvertFrom-Json
$expectedDlls = @($manifest.$Variant)
if ($expectedDlls.Count -ne 28) { throw "Expected 28 frozen host DLLs for $Variant." }
foreach ($item in $expectedDlls) {
    $path = Join-Path $hostRoot $item.Name
    if (-not (Test-Path -LiteralPath $path) -or (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -ne $item.SHA256) {
        throw "Frozen DLL mismatch: $Variant/$($item.Name)"
    }
}
$library = Join-Path $hostRoot 'Marimo.Kotowari.dll'
$input = Join-Path $hostRoot 'Data/test.json'
if ((Get-FileHash -LiteralPath $library -Algorithm SHA256).Hash -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') { throw 'Fixed Kotowari DLL SHA mismatch.' }
if ((Get-FileHash -LiteralPath $input -Algorithm SHA256).Hash -ne 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D') { throw 'Frozen input SHA mismatch.' }
$null = New-Item -ItemType Directory -Path $runRoot -Force

$start = [Diagnostics.ProcessStartInfo]::new((Get-Command dotnet).Source)
$start.WorkingDirectory = $hostRoot
$start.UseShellExecute = $false
$start.CreateNoWindow = $true
$start.RedirectStandardOutput = $true
$start.RedirectStandardError = $true
foreach ($argument in @('StringExecutionRecovery.ChildHarness.dll','--benchmarkName','Marimo.Kotowari.Benchmarks.JsonStreamBenchmarks.StringInput','--benchmarkId','0')) { [void]$start.ArgumentList.Add($argument) }
$start.Environment['DOTNET_TieredPGO'] = '1'
$start.Environment['DOTNET_JitDisasm'] = 'Marimo.*!*'
$start.Environment['DOTNET_JitDisasmWithCodeBytes'] = '1'
$start.Environment['DOTNET_JitStdOutFile'] = Join-Path $runRoot 'jit.asm'
$process = [Diagnostics.Process]::Start($start)
if (-not $process) { throw "Failed to start $Variant JIT diagnostic harness." }
$processId = $process.Id
$process.ProcessorAffinity = [IntPtr]4
if ($process.ProcessorAffinity.ToInt64() -ne 4) { throw 'Affinity was not set to 4.' }
$stdoutTask = $process.StandardOutput.ReadToEndAsync()
$stderrTask = $process.StandardError.ReadToEndAsync()
$startedUtc = [DateTime]::UtcNow
$watch = [Diagnostics.Stopwatch]::StartNew()
try {
    while (-not $process.WaitForExit(1000)) {
        if ($watch.Elapsed.TotalSeconds -gt 180) { $process.Kill($true); throw 'JIT diagnostic timed out after 180 seconds.' }
    }
    $exitCode = $process.ExitCode
    $endedUtc = [DateTime]::UtcNow
    $stdout = $stdoutTask.GetAwaiter().GetResult()
    $stderr = $stderrTask.GetAwaiter().GetResult()
    [IO.File]::WriteAllText((Join-Path $runRoot 'stdout.log'),$stdout,[Text.UTF8Encoding]::new($false))
    [IO.File]::WriteAllText((Join-Path $runRoot 'stderr.log'),$stderr,[Text.UTF8Encoding]::new($false))
    if ($exitCode -ne 0) { throw "JIT diagnostic exit code $exitCode; raw output retained." }
    if ($stderr.Trim().Length -ne 0) { throw 'JIT diagnostic wrote to stderr; raw output retained.' }
    if ($stdout -notmatch '(?m)^// AfterAll\s*$') { throw 'Missing // AfterAll completion marker.' }
    $actualCount = [regex]::Matches($stdout,'(?m)^WorkloadActual\s+\d+:').Count
    $resultCount = [regex]::Matches($stdout,'(?m)^WorkloadResult\s+\d+:').Count
    $asmPath = Join-Path $runRoot 'jit.asm'
    if (-not (Test-Path -LiteralPath $asmPath)) { throw 'JIT disassembly file was not produced.' }
    $asm = [IO.File]::ReadAllText($asmPath)
    $headers = [regex]::Matches($asm,'(?m)^; Assembly listing for method .+$')
$targetHeaders = @($headers | Where-Object Value -Match 'ExpectCharParser|ConditionalCharParser|JSON')
    $record = [ordered]@{
        Variant=$Variant; ProcessId=$processId; ExitCode=$exitCode
        StartUTC=$startedUtc.ToString('o'); EndUTC=$endedUtc.ToString('o'); WallSeconds=$watch.Elapsed.TotalSeconds
        Affinity=4; TieredPGO=1; JitDisasm='Marimo.*!*'; JitDisasmWithCodeBytes=1
        ActualCount=$actualCount; ResultCount=$resultCount
        InputBytes=(Get-Item -LiteralPath $input).Length; InputSHA256=(Get-FileHash -LiteralPath $input -Algorithm SHA256).Hash
        LibrarySHA256=(Get-FileHash -LiteralPath $library -Algorithm SHA256).Hash
        ParserSHA256=(Get-FileHash -LiteralPath (Join-Path $hostRoot 'Marimo.Parser.dll') -Algorithm SHA256).Hash
        DLLManifestSHA256=(Get-FileHash -LiteralPath (Join-Path $root 'dll-manifest.json') -Algorithm SHA256).Hash
        JitOutputBytes=(Get-Item -LiteralPath $asmPath).Length; JitOutputSHA256=(Get-FileHash -LiteralPath $asmPath -Algorithm SHA256).Hash
        AssemblyMethodHeaderCount=$headers.Count; RelevantMethodHeaderCount=$targetHeaders.Count
        RelevantMethodHeaders=@($targetHeaders | ForEach-Object Value)
        DiagnosticOnly=$true; OutputFiles=@('jit.asm','stdout.log','stderr.log')
    }
    $record | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $runRoot 'capture.json') -Encoding utf8
    if ($actualCount -ne 8 -or $resultCount -ne 8) { throw "Expected 8 Actual and 8 Result windows; got $actualCount/$resultCount." }
    if ($targetHeaders.Count -eq 0) { throw 'No JSON/character-parser method was emitted in JIT output.' }
    Write-Output ($record | ConvertTo-Json -Compress)
} finally {
    if (-not $process.HasExited) { $process.Kill($true); $process.WaitForExit() }
    $process.Dispose()
}

$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$repo = (Resolve-Path (Join-Path $root '../..')).Path
$helperRoot = Join-Path $repo 'artifacts/string-next-after-whitespace-2026-10-19'
