if (-not (Test-Path -LiteralPath $statusPath)) { throw "Power helper status is missing: $statusPath" }
$helper = Get-Content -LiteralPath $statusPath -Raw | ConvertFrom-Json -DateKind String
$now = [DateTimeOffset]::UtcNow
$heartbeat = [DateTimeOffset]::Parse($helper.LastHeartbeatUtc)
$heartbeatAge = ($now - $heartbeat).TotalSeconds
if ($helper.Reason -ne 'Running' -or [long]$helper.AcquireReturn -ne 2147483648 -or [DateTimeOffset]::Parse($helper.DeadlineUtc) -le $now) {
    throw 'Power helper is not active or its system-required request is not confirmed.'
}
if ($heartbeatAge -lt -5 -or $heartbeatAge -gt 90) { throw "Power helper heartbeat is stale: age $heartbeatAge seconds." }

