$power = New-Object RecursiveDefinitionPowerStatus
if (-not [RecursiveDefinitionPowerStatusApi]::GetSystemPowerStatus([ref]$power)) { throw "GetSystemPowerStatus failed: $([Runtime.InteropServices.Marshal]::GetLastWin32Error())" }
if ($power.ACLineStatus -ne 1 -or $power.SystemStatusFlag -ne 0) { throw "Power condition mismatch: AC=$($power.ACLineStatus), saver=$($power.SystemStatusFlag)." }
[ordered]@{TimestampUTC=$now.ToString('o');HelperPid=$helper.Pid;HeartbeatUTC=$heartbeat.ToString('o');HeartbeatAgeSeconds=$heartbeatAge;DeadlineUTC=$helper.DeadlineUtc;AcquireReturn=$helper.AcquireReturn;ACLineStatus=[int]$power.ACLineStatus;BatterySaver=[int]$power.SystemStatusFlag;Ready=$true} | ConvertTo-Json -Compress

